{"tiddlers":{"$:/plugins/tobibeer/appear/popup.js":{"title":"$:/plugins/tobibeer/appear/popup.js","module-type":"utils","type":"application/javascript","text":"/*\
title: $:/plugins/tobibeer/appear/popup.js
type: application/javascript
module-type: utils
\*/
(function(){"use strict";
var t=require("$:/core/modules/utils/dom/popup.js").Popup,
    e=require("$:/core/modules/widgets/reveal.js").reveal,
    s=e.prototype.refresh;

// TYLER'S DIRECTIVE: Save the pristine modern TiddlyWiki core function
var originalShow = t.prototype.show;

t.prototype.show = function(options) {
    // TYLER'S DIRECTIVE: always use the pristine modern TiddlyWiki core popup.
    // The legacy tobibeer `tc-popup-absolute` offsetParent math has been removed:
    // core's `absolute: true` option (with the "@" coordinate prefix) already
    // handles page-absolute positioning natively, correctly, and without any
    // hard-coded offsets. This override exists only to neutralise the legacy
    // shim shipped by the external quickview plugin. This override only works
    // because this tiddler shadows the external quickview plugin's copy of the
    // same title; if that shadow relationship ever changes, verify that the
    // wrapped `show` is still core's and not the legacy shim.
    originalShow.apply(this, arguments);
};

t.prototype.popupInfo=function(t){var e,s=false,p=t;while(p&&e===undefined){if($tw.utils.hasClass(p,"tc-popup-handle")||$tw.utils.hasClass(p,"tc-popup-keep")){s=true}if($tw.utils.hasClass(p,"tc-reveal")&&($tw.utils.hasClass(p,"tc-popup")||$tw.utils.hasClass(p,"tc-popup-handle"))){e=parseInt(p.style.zIndex)-1e3}p=p.parentNode}var o={popupLevel:e||0,isHandle:s};return o};
t.prototype.handleEvent=function(t){if(t.type==="click"){var e=this.popupInfo(t.target),s=e.popupLevel-1;if(e.isHandle){if(s<0){s=1}else{s++}}this.cancel(s)}};
e.prototype.refresh=function(){var t,e,p=this.isOpen;e=s.apply(this,arguments);t=this.domNodes[0];if(this.isOpen&&(p!==this.isOpen||!t.style.zIndex)&&t&&(this.type==="popup"||$tw.utils.hasClass(t,"tc-block-dropdown")&&$tw.utils.hasClass(t,"tc-reveal"))){t.style.zIndex=1e3+$tw.popup.popups.length}return e}

if (typeof document !== "undefined" && !document.hasAppearEscListener) {
    document.hasAppearEscListener = true;
    document.addEventListener("keydown", function(e) {
        if (e.key === "Escape" || e.keyCode === 27) {
            $tw.popup.cancel(0);
        }
    }, true); // useCapture=true ensures it runs before child elements can stopPropagation
    document.addEventListener("contextmenu", function() {
        $tw.popup.cancel(0);
    }, true);
}

})();"},"$:/plugins/tobibeer/preview/link.js":{"title":"$:/plugins/tobibeer/preview/link.js","module-type":"startup","type":"application/javascript","text":"/*title: $:/plugins/tobibeer/preview/link.js
type: application/javascript
module-type: startup

Hover-preview for wikilinks (tobibeer/preview, patched by Lithic):
- Positions previews with core's native absolute coordinates
  (triggerPopup with absolute:true + "@" state prefix), which keeps them
  correct under page scroll, nested containers and the adjustable sidebar.
- Deliberate sidebar behaviour: when the hovered link lives inside a sidebar
  container (.nc-sidebar / .tc-sidebar / .tc-sidebar-scrollable), the preview
  is shifted sideways past the sidebar's edge by the sidebar's live width, so
  it floats over the story area instead of obscuring sidebar contents. This
  restores the useful part of the old broken offset math on purpose.
\*/
(function(){

"use strict";

var link = require("$:/core/modules/widgets/link.js").link,
	render = link.prototype.render,
	handleClickEvent = link.prototype.handleClickEvent;

link.prototype.render = function() {
	render.apply(this, arguments);
	var self = this,
		wiki = this.wiki,
		domNode = this.domNodes[0],
		tiddler = wiki.getTiddler(this.to),
		defaults = "$:/plugins/tobibeer/preview/defaults/",
		preview = "$:/temp/tobibeer/preview-",
		keyDescriptor = $tw.utils.parseKeyDescriptorTB(wiki.getTextReference(defaults + "keys", "").toUpperCase()),
		delay = wiki.getTextReference(defaults + "delay", "").toUpperCase(),
		hovering = 0, // per-link hover lock (the upstream original shared this flag module-wide)
		// If a preview is already open for this tiddler at this level, don't re-trigger
		getPopupInfo = function(node) {
			var info = $tw.popup.popupInfo(node),
				level = info.popupLevel;
			return wiki.getTextReference(preview + level) && wiki.getTextReference(preview + level + "-tiddler") === self.to ? null : info;
		},
		// Horizontal shift (away from the sidebar edge) when the link lives
		// inside a sidebar container; 0 otherwise. Measured live so it tracks
		// the adjustable sidebar width with no hard-coded pixels.
		sidebarShift = function(node) {
			var el = node;
			while(el && el !== document.body) {
				if($tw.utils.hasClass(el, "nc-sidebar") || $tw.utils.hasClass(el, "tc-sidebar") || el.id === "tc-sidebar" || $tw.utils.hasClass(el, "tc-sidebar-scrollable")) {
					var rect = el.getBoundingClientRect();
					return rect.width ? (rect.left < window.innerWidth / 2 ? rect.width : -rect.width) : 0;
				}
				el = el.parentNode;
			}
			return 0;
		},
		triggerPreview = function() {
			var info = getPopupInfo(domNode),
				level;
			if(info) {
				level = info.popupLevel;
				clearTimeout(self.previewTimeout);
				$tw.popup.cancel(level);
				level++;
				wiki.setText(preview + level + "-tiddler", "text", null, self.to);
				if($tw.popup.findPopup(preview + level) === -1) {
					setTimeout(function() {
						$tw.popup.triggerPopup({domNode: domNode, title: preview + level, wiki: wiki, absolute: true});
						// Sidebar-aware offset: push the preview past the sidebar's
						// edge so it never covers sidebar contents. Repositioning an
						// already-open reveal relies on the bundled preview/popups
						// template override carrying updatePopupPosition="yes" - keep
						// both tiddlers installed together.
						var shift = sidebarShift(domNode);
						if(shift) {
							var state = wiki.getTextReference(preview + level, ""),
								coords = /^@\((-?[0-9.E]+),(-?[0-9.E]+),(-?[0-9.E]+),(-?[0-9.E]+)\)$/.exec(state);
							if(coords) {
								wiki.setTextReference(preview + level, "@(" + (parseFloat(coords[1]) + shift) + "," + coords[2] + "," + coords[3] + "," + coords[4] + ")");
							}
						}
						hovering = 0;
					}, 50);
				}
			}
		},
		shouldPreview = function() {
			if($tw.utils.hasClass(domNode, "tc-freelink")) {
				return false;
			}
			var not = wiki.getTextReference(defaults + "not", ""),
				exclude = wiki.getTextReference(defaults + "exclude", ""),
				ok = true;
			if(not) {
				$tw.utils.each(not.split(" "), function(className) {
					var node = domNode;
					while(node && ok) {
						if($tw.utils.hasClass(node, className)) {
							ok = false;
							return false;
						}
						node = node.parentNode;
					}
				});
			}
			if(ok && exclude) {
				var excluded = wiki.filterTiddlers(exclude);
				if(excluded.indexOf(self.to) >= 0) {
					ok = false;
				}
			}
			return ok;
		};
	delay = delay !== undefined ? parseInt(delay) : null;
	if(delay !== null && isNaN(delay)) {
		delay = 0;
	}
	if(tiddler) {
		$tw.utils.addClass(domNode, "tc-popup-handle");
		["mouseover", "mouseout", "contextmenu"].forEach(function(eventName) {
			domNode.addEventListener(eventName, function(event) {
				event = event || window.event;
				if(eventName === "mouseover") {
					if(self._previewSuppressed) {
						return;
					}
					if(shouldPreview()) {
						if(!event.keyCode) {
							event.keyCode = 0;
						}
						if($tw.utils.checkKeyDescriptorTB(event, keyDescriptor)) {
							if(!hovering) {
								hovering = 1;
								triggerPreview();
							}
						} else if(delay !== null) {
							hovering = 0;
							self.previewTimeout = setTimeout(triggerPreview, delay);
						}
					}
				} else if(eventName === "contextmenu") {
					hovering = 0;
					self._previewSuppressed = true;
					clearTimeout(self.previewTimeout);
					$tw.popup.cancel(0);
				} else {
					hovering = 0;
					self._previewSuppressed = false;
					clearTimeout(self.previewTimeout);
				}
			});
		});
	}
};

link.prototype.handleClickEvent = function() {
	handleClickEvent.apply(this, arguments);
	clearTimeout(this.previewTimeout);
	$tw.popup.cancel(Math.max(0, $tw.popup.popupInfo(this.domNodes[0]).popupLevel));
};

})();
"},"$:/plugins/tobibeer/preview/popups":{"title":"$:/plugins/tobibeer/preview/popups","tags":"$:/tags/PageTemplate","type":"text/vnd.tiddlywiki","text":"\define state(num)
$:/temp/tobibeer/preview-$num$
\end

\define classes(num)
tc-popup appear appear-block appear-reveal tc-preview-tiddler tc-preview-tiddler-$num$ $(default-classes)$
\end

\define level(num)
<$reveal tag="div" type="popup" state=<<state $num$>> class=<<classes $num$>> clamp="right" updatePopupPosition="yes">
<$tiddler tiddler={{$:/temp/tobibeer/preview-$num$-tiddler}}>
<$transclude tiddler={{$:/plugins/tobibeer/preview/defaults/template}} mode="block"/>
</$tiddler>
</$reveal>
\end

<$vars default-classes={{$:/plugins/tobibeer/preview/defaults/class}}>
<$list filter="1 2 3 4 5 6 7 8 9">
<$macrocall $name="level" num={{!!title}}/>
</$list>
</$vars>
<style>
/* Appear preview popovers must never stretch the page horizontally: cap the
   popup to the viewport width (keeping the plugin's 600px ceiling on wide
   screens) and scroll any content that is wider than the popup itself.
   clamp="right" on the reveals above keeps the popup inside the viewport's
   right edge; this style is the companion that guarantees no page scrollbar.
   Note: keep the 2rem margin - 100vw includes the scrollbar width while core's
   clamp measures against window.innerWidth, so 2rem is the slack that keeps
   the popup strictly inside the viewport. */
.tc-popup.tc-preview-tiddler.appear-reveal {
	max-width: min(600px, calc(100vw - 2rem));
	overflow: auto;
}
</style>"},"$:/plugins/tobibeer/preview/template":{"title":"$:/plugins/tobibeer/preview/template","text":"<div class="tc-title">&nbsp;<i class="fa fa-file-alt"/>&ensp;{{!!title}}</div>
{{||$:/core/ui/ViewTemplate/subtitle}}
{{||$:/core/ui/ViewTemplate/tags}}

<$list filter="[all[current]has[stream-list]!has[text]]" variable="ignore">
  <$macrocall $name="embed-stream" parent=<<currentTiddler>>/>
</$list>
<$list filter="[all[current]!has[stream-list]] [all[current]has[text]] +[limit[1]]" variable="ignore">
  <$transclude mode="block"/>
</$list>
"}}}
